INSERT INTO "tasks" VALUES('task_7ftXA9BaLkI6FHHRkWcyH','Export the public agent directory to CSV with a capability histogram','Export every public agent profile from api.basedagents.ai to a clean CSV: agent_id, name, status, capabilities (pipe-joined), protocols, organization, wallet_network, reputation_score, verification_count, registered_at, last_seen. Use the public directory/search endpoints with polite pagination (<= 1 request/second).

