INSERT INTO "tasks" VALUES('task_HsRZZWw01h84hPv60us9F','AEO check: Grok · cómo sacar hipoteca CR · geo Costa Rica','AEO citation check for credito.cr. Query Grok only (xAI product; not ChatGPT/Claude/other) from a Costa Rica geo context if available.

